INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('02813f6c-e6d0-4cd3-9138-2325192bc1aa', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Database Creator', 'Create database shopdb using createdb. Run: psql -l | grep shopdb. What is the output?', 50, '$2b$10$jf38m2H7D6mmsqmVwmYC2eVNoPGF/CsY34BYclS3j602wLX/2TDtm');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('91468c0d-1c68-4bd1-8912-771b660bff43', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Table Architect', 'Create table products (id SERIAL PRIMARY KEY, name VARCHAR(50), price NUMERIC(10,2), stock INT DEFAULT 0). Run: \d products | wc -l. How many lines of column info?', 75, '$2b$10$/Cxv9J5Xs5iLcX0bmtObVuYsZoV/ER.gH5CXdKuZ0T80PBzxg.TOW');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('463aa7d2-b8fd-45de-848a-83be97da698f', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$yaUNchcAUWhIePGAD266XOFoNxQZAlnNj2cdQsGEndWLoVMZ0CRCG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('40dd62c8-75dc-4533-9650-dc3ee93304c0', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product?', 75, '$2b$10$EX.m4Djsj68Xa7GxIqqzputm3V3v50KLL/h1DxgB2gayDHYJ4ogau');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('301e99da-919b-489c-b9b2-9efe339d39cf', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Index Builder', 'Create index idx_products_name on products(name). Run: \di | grep idx_products_name. What index name is shown?', 100, '$2b$10$bKDE.eY5Jv80V5Kxw1nYtuf2ItHKdu6z1YR4oMhXBHeoT5iEPBepq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('51cc07f0-e808-41c9-b91b-33c9d0314cde', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Role Manager', 'Create role appuser LOGIN PASSWORD ''secret123''; Grant CONNECT on shopdb to appuser. Run: \du | grep appuser. What is listed?', 100, '$2b$10$wysCfiVWhoe.ITbrfGRd5uy6jZLIubUkbMEfxlMNQo/1WV/a7X1NC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0981f33d-f6bf-4420-b287-42d4901d33f3', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Backup Creator', 'Run: pg_dump shopdb > /tmp/pgbackup.sql && wc -l /tmp/pgbackup.sql. How many lines?', 100, '$2b$10$bDLOU/hopu.jXB3DsoBJXOcjWFCc7bhu43YphwVOITvu0/ovUwXBS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f396ecd8-a7a0-4aa1-bfc8-ea63f01a0036', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Join Artist', 'Create table orders (id SERIAL PRIMARY KEY, product_id INT REFERENCES products(id), quantity INT). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id. How many rows (excluding header)?', 100, '$2b$10$rip4r1iFAL2aA4SwjcVvweZp9d6Nl4qfKQZoKaNvybVkovJQMqDFO');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6013b23e-6c5c-4839-8392-6f2154f08978', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total?', 100, '$2b$10$LI/SJTgWs87uo2YQwswU0OJgLtvCAPgAEgHMC.XKomGi0VuBLy26S');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('51380095-ef93-4ac3-a567-cb1ddb90a8db', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Transaction Tester', 'Run: psql shopdb -c "BEGIN; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && psql shopdb -c "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$eowZYvISwGLWb1BTDmU8iuKdCg3Ch7EMaL1ML2tJDMz0Mq660Xi8m');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('491f7fa9-46f1-4b2a-bbfe-0a4863eff952', '993d7511-1cc8-48e1-a817-9a73b1425405', 'View Creator', 'Create view cheap_products AS SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product?', 100, '$2b$10$Vmu7dd2PakPiHf82RtSJ8OzJXEH7Np9hnrHaRhC6tACyklXRfeFqy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('52a7b73c-5704-4e38-b74d-4c99bcc37485', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Permission Auditor', 'Run: psql -c "SELECT has_table_privilege(''appuser'', ''products'', ''SELECT'')". What is the result?', 75, '$2b$10$fAe7ldlgvxwM/LDc7pfrLO3VhpnreqL1EfzF4peo6yxAztcc2HpUK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('181ae443-56ef-4b7b-8275-feb78beb5467', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Schema Inspector', 'Run: psql shopdb -c "\dt" | grep -c "product". How many tables match?', 75, '$2b$10$OxC9/BGeNkO6dh6XCm.1fuywbhQh2yPfNPfQlJ7jRf8U3BD95V8d6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8553519f-c3f5-4a81-9d91-37b6413e7987', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Serial Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$YFGmTIBv0qoRAVWCNDq6DOeZoA6TzzMvfwxIkR7ZSK40oEOK5rSCy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('91efac6b-e22d-4c0b-a645-5722a81f4772', '993d7511-1cc8-48e1-a817-9a73b1425405', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name=''Mouse'' and SELECT price FROM products WHERE name=''Mouse''. What is the new price (rounded to 2 decimals)?', 100, '$2b$10$95sj7CCbPnUv5MlgmPU3fOkYjGoS5Ln0QqO8g04u3a0yiMx3S8hn2');
